import os, uuid, time, logging, datetime as dt
import jwt, bcrypt, redis
from flask import Flask, request, jsonify

KEYS = '/app/keys'
LOG = '/app/logs/app.log'
ISS = 'rsa-jwt-api'
ACCESS_TTL = 15 * 60
REFRESH_TTL = 7 * 24 * 3600

os.makedirs('/app/logs', exist_ok=True)
logging.basicConfig(filename=LOG, level=logging.INFO, format='%(asctime)s %(levelname)s api %(message)s')
log = logging.getLogger('api')

with open(KEYS + '/private.pem', 'rb') as f:
    PRIV = f.read()
with open(KEYS + '/public.pem', 'rb') as f:
    PUB = f.read()

r = redis.Redis(host=os.environ.get('REDIS_HOST', 'localhost'), port=int(os.environ.get('REDIS_PORT', '6379')), decode_responses=True)
USERS = {'admin': bcrypt.hashpw(b'password123', bcrypt.gensalt()).decode()}

app = Flask(__name__)

def fail(code, msg):
    log.error('HTTP %d: %s', code, msg)
    return jsonify(error=msg), code

def make_token(sub, ttype, ttl):
    now = dt.datetime.now(dt.timezone.utc)
    payload = {'iss': ISS, 'sub': sub, 'iat': now, 'exp': now + dt.timedelta(seconds=ttl), 'jti': str(uuid.uuid4()), 'type': ttype}
    return jwt.encode(payload, PRIV, algorithm='RS256')

def check(tok, expected=None):
    try:
        p = jwt.decode(tok, PUB, algorithms=['RS256'], issuer=ISS, options={'require': ['exp', 'iat', 'jti', 'sub', 'iss']})
    except jwt.ExpiredSignatureError:
        return None, (401, 'token expired')
    except jwt.PyJWTError as e:
        return None, (401, 'invalid token: %s' % e)
    if expected and p.get('type') != expected:
        return None, (401, 'wrong token type, expected %s' % expected)
    if r.exists('blacklist:' + p['jti']):
        return None, (403, 'token revoked')
    return p, None

def bearer():
    h = request.headers.get('Authorization', '')
    if h.startswith('Bearer '):
        return h[7:].strip()
    return request.args.get('token')

@app.post('/auth/login')
def login():
    d = request.get_json(silent=True) or {}
    u = str(d.get('username', ''))
    pw = str(d.get('password', ''))
    h = USERS.get(u)
    if not h or not bcrypt.checkpw(pw.encode(), h.encode()):
        return fail(401, 'invalid credentials')
    log.info('login ok user=%s', u)
    return jsonify(access_token=make_token(u, 'access', ACCESS_TTL), refresh_token=make_token(u, 'refresh', REFRESH_TTL), token_type='Bearer', expires_in=ACCESS_TTL)

@app.post('/auth/refresh')
def refresh():
    d = request.get_json(silent=True) or {}
    p, e = check(str(d.get('refresh_token', '')), 'refresh')
    if e:
        return fail(*e)
    log.info('refresh ok sub=%s', p['sub'])
    return jsonify(access_token=make_token(p['sub'], 'access', ACCESS_TTL), token_type='Bearer', expires_in=ACCESS_TTL)

@app.post('/auth/revoke')
def revoke():
    d = request.get_json(silent=True) or {}
    p, e = check(str(d.get('token', '')))
    if e:
        return fail(*e)
    ttl = int(p['exp'] - time.time())
    if ttl > 0:
        r.set('blacklist:' + p['jti'], 'revoked', ex=ttl)
    log.info('revoked jti=%s type=%s ttl=%d', p['jti'], p.get('type'), ttl)
    return jsonify(revoked=True, jti=p['jti'], type=p.get('type'))

@app.get('/auth/validate')
def validate():
    t = bearer()
    if not t:
        return fail(401, 'missing token')
    p, e = check(t)
    if e:
        return fail(*e)
    return jsonify(valid=True, sub=p['sub'], jti=p['jti'], type=p['type'], exp=p['exp'])

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
